mapper.update:
UPDATE rag_entity e SET embedding = v.embedding, updated_at = NOW() FROM ( VALUES
(#{item.id}, #{item.embedding,typeHandler=com.smart.rag.rag.mapper.VectorTypeHandler}::vector)
) AS v(id, embedding) WHERE e.id = v.id

UPDATE rag_entity e SET community_id = v.community_id, updated_at = NOW() FROM ( VALUES
(#{c.entityId}, #{c.communityId})
) AS v(entity_id, community_id) WHERE e.id = v.entity_id AND e.user_id = #{userId,jdbcType=BIGINT} AND e.community_id IS DISTINCT FROM v.community_id

UPDATE rag_entity e SET weak_tie_score = v.weak_tie_score, updated_at = NOW() FROM ( VALUES
(#{item.entityId}, #{item.weakTieScore})
) AS v(entity_id, weak_tie_score) WHERE e.id = v.entity_id AND e.weak_tie_score IS DISTINCT FROM v.weak_tie_score

UPDATE rag_entity e SET bridge_score = v.bridge_score, updated_at = NOW() FROM ( VALUES
(#{item.entityId}, #{item.bridgeScore})
) AS v(entity_id, bridge_score) WHERE e.id = v.entity_id AND e.bridge_score IS DISTINCT FROM v.bridge_score

mapper.select:
WITH seed_embeddings(embedding) AS ( VALUES
(#{emb,typeHandler=com.smart.rag.rag.mapper.VectorTypeHandler}::vector)
), entity_match AS ( SELECT e.id, e.name_display, MAX(1 - (e.embedding <=> se.embedding)) AS query_relevance, COALESCE(e.bridge_score, 0) AS bridge, COALESCE(e.weak_tie_score, 0.5) AS weak_tie, e.degree FROM rag_entity e CROSS JOIN seed_embeddings se WHERE e.user_id = #{userId,jdbcType=BIGINT} AND (#{teamId,jdbcType=BIGINT} IS NULL AND e.team_id IS NULL OR e.team_id = #{teamId,jdbcType=BIGINT}) AND e.embedding IS NOT NULL AND (1 - (e.embedding <=> se.embedding)) > #{matchThreshold} GROUP BY e.id, e.name_display, e.bridge_score, e.weak_tie_score, e.degree ), normalized AS ( SELECT *, COALESCE(query_relevance / NULLIF(max(query_relevance) OVER (), 0), 0) AS query_rel_norm, COALESCE(bridge / NULLIF(max(bridge) OVER (), 0), 0) AS bridge_norm, COALESCE(weak_tie / NULLIF(max(weak_tie) OVER (), 0), 0) AS weak_tie_norm FROM entity_match ), scored AS ( SELECT *, ( #{alpha} * query_rel_norm + #{beta} * bridge_norm + #{gamma} * weak_tie_norm ) AS composite_score FROM normalized ) SELECT * FROM scored ORDER BY composite_score DESC LIMIT #{frontierBudget}

WITH frontier(id, name_display, composite_score) AS ( VALUES
(#{fe.id}::bigint, #{fe.nameDisplay}::text, #{fe.compositeScore}::double precision)
), aggregated AS ( SELECT ce.chunk_id, MAX(f.composite_score) AS chunk_score, array_to_string(array_agg(f.name_display ORDER BY f.composite_score DESC), ',') AS voted_by_entities FROM frontier f JOIN rag_chunk_entity ce ON ce.entity_id = f.id WHERE EXISTS ( SELECT 1 FROM vector_store vs WHERE vs.id = ce.chunk_id AND vs.metadata->>'userId' = #{userIdStr} ) GROUP BY ce.chunk_id ORDER BY chunk_score DESC LIMIT #{chunkTopK} ) SELECT a.chunk_id, vs.content, vs.metadata::text AS metadata, a.chunk_score, a.voted_by_entities FROM aggregated a JOIN vector_store vs ON vs.id = a.chunk_id ORDER BY a.chunk_score DESC

WITH frontier_with_score(id, composite_score) AS ( VALUES
(#{fe.id}::bigint, #{fe.compositeScore}::double precision)
), seed_events AS ( SELECT DISTINCT e.id AS event_id, e.chunk_id FROM rag_event e JOIN rag_chunk_entity ce ON ce.chunk_id = e.chunk_id WHERE ce.entity_id IN (SELECT id FROM frontier_with_score) AND e.user_id = #{userId,jdbcType=BIGINT} AND (#{teamId,jdbcType=BIGINT} IS NULL AND e.team_id IS NULL OR e.team_id = #{teamId,jdbcType=BIGINT}) ), expanded_entities AS ( SELECT DISTINCT ce.entity_id FROM rag_chunk_entity ce JOIN seed_events se ON se.chunk_id = ce.chunk_id LEFT JOIN frontier_with_score f ON f.id = ce.entity_id JOIN rag_entity e2 ON e2.id = ce.entity_id WHERE f.id IS NULL AND e2.user_id = #{userId,jdbcType=BIGINT} ), expanded_events AS ( SELECT DISTINCT e.id AS event_id, e.chunk_id FROM rag_event e JOIN rag_chunk_entity ce ON ce.chunk_id = e.chunk_id WHERE ce.entity_id IN (SELECT entity_id FROM expanded_entities) AND e.user_id = #{userId,jdbcType=BIGINT} ), aggregated AS ( SELECT ee.chunk_id, #{expansionDecay} * MAX(f.composite_score) AS chunk_score, array_to_string(array_agg(DISTINCT ex.entity_id), ',') AS discovered_via_entities FROM expanded_events ee JOIN rag_chunk_entity ex ON ex.chunk_id = ee.chunk_id JOIN frontier_with_score f ON f.id = ex.entity_id WHERE EXISTS ( SELECT 1 FROM vector_store vs WHERE vs.id = ee.chunk_id AND vs.metadata->>'userId' = #{userIdStr} ) GROUP BY ee.chunk_id ORDER BY chunk_score DESC LIMIT #{expandChunkTopK} ) SELECT a.chunk_id, vs.content, vs.metadata::text AS metadata, a.chunk_score, a.discovered_via_entities FROM aggregated a JOIN vector_store vs ON vs.id = a.chunk_id ORDER BY a.chunk_score DESC
